import { Logger } from '@nestjs/common';
import { getDocument, listDocumentKeys } from '../../utils/aws/s3.js';

/**
 * An AWS account a business has handed us for measurement.
 */
export class MeteredAccount {
    /**
     * The account the metering role lives in.
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * The role we assume to read the account.
     * @example "arn:aws:iam::445566778899:role/metering-metering"
     */
    public roleArn: string;
    /**
     * The external id the role's trust policy asks for, when it asks for one.
     */
    public externalId?: string;
    /**
     * The region the business runs the metered workload in.
     * @example "us-east-1"
     */
    public region: string;
}

/**
 * One account a customer was onboarded onto. A dedicated account holds nothing
 * but that customer's workload, so everything measured in it belongs to them.
 */
export class OnboardedAccount {
    /**
     * @example "445566778899"
     */
    public accountId: string;
    /**
     * True when the account is dedicated to this customer alone.
     */
    public dedicated?: boolean;
}

/**
 * The per customer onboarding record kept in the business' metering bucket. A
 * customer is only billable for an account it has a record for.
 */
export class CustomerOnboardingRecord {
    private static readonly logger = new Logger(CustomerOnboardingRecord.name);
    public customerId: string;
    public displayName?: string;
    public accounts: Array<OnboardedAccount>;

    /**
     * Reads every onboarding record sitting under the prefix, one object per
     * customer. Records we cannot read or parse are skipped, they simply do not
     * make their customer billable.
     */
    static async loadAll(bucket: string, prefix: string): Promise<Array<CustomerOnboardingRecord>> {
        if (!bucket || !prefix) {
            CustomerOnboardingRecord.logger.warn(
                'No customer onboarding record location given, no usage can be attributed',
            );
            return [];
        }
        const keys = await listDocumentKeys(bucket, prefix);
        const records = await Promise.all(
            keys.map(async (key) => {
                try {
                    return await getDocument<CustomerOnboardingRecord>(bucket, key);
                } catch (e) {
                    CustomerOnboardingRecord.logger.error(`Couldn't read onboarding record ${key}`, e);
                    return undefined;
                }
            }),
        );
        return records.filter((record) => record && record.customerId && Array.isArray(record.accounts));
    }
}

/**
 * How an account is tenanted: either dedicated to a single customer, or shared
 * by the customers genuinely onboarded onto it.
 */
export class AccountTenancy {
    public accountId: string;
    /**
     * Set when exactly one customer holds the account for itself.
     */
    public dedicatedTo?: string;
    /**
     * Every customer onboarded onto the account.
     */
    public tenants: Array<string>;

    constructor({ accountId, dedicatedTo, tenants }: AccountTenancy) {
        this.accountId = accountId;
        this.dedicatedTo = dedicatedTo;
        this.tenants = tenants;
    }

    get isDedicated(): boolean {
        return !!this.dedicatedTo;
    }

    /**
     * Whether the customer is onboarded onto this account.
     */
    hasTenant(customerId: string): boolean {
        return this.tenants.includes(customerId);
    }
}

/**
 * The onboarding record a business keeps in its metering bucket. It is written
 * by the onboarding flow and read by every collector that has to sweep more
 * than one account.
 */
export class MeteringRegistry {
    public businessID: string;
    /**
     * Key prefix the per customer onboarding records sit under in the same
     * bucket, one object per customer.
     * @example "onboarding/customers/"
     */
    public customerRecordPrefix: string;
    public accounts: Array<MeteredAccount>;

    static async load(bucket: string, key: string): Promise<MeteringRegistry> {
        return getDocument<MeteringRegistry>(bucket, key);
    }

    /**
     * Works out who is billable for each account by reading the per customer
     * onboarding records that live beside this registry.
     */
    static async loadTenancy(bucket: string, registry: MeteringRegistry): Promise<Record<string, AccountTenancy>> {
        const records = await CustomerOnboardingRecord.loadAll(bucket, registry?.customerRecordPrefix);
        return MeteringRegistry.buildTenancy(records);
    }

    static buildTenancy(records: Array<CustomerOnboardingRecord>): Record<string, AccountTenancy> {
        const tenants: Record<string, Array<string>> = {};
        const dedicatedClaims: Record<string, Array<string>> = {};
        (records ?? []).forEach((record) => {
            (record?.accounts ?? []).forEach((account) => {
                if (!account?.accountId) {
                    return;
                }
                const accountId = `${account.accountId}`;
                if (!(tenants[accountId] ?? []).includes(record.customerId)) {
                    tenants[accountId] = (tenants[accountId] ?? []).concat(record.customerId);
                }
                if (account.dedicated) {
                    dedicatedClaims[accountId] = (dedicatedClaims[accountId] ?? []).concat(record.customerId);
                }
            });
        });
        return Object.keys(tenants).reduce((acc, accountId) => {
            const claims = dedicatedClaims[accountId] ?? [];
            acc[accountId] = new AccountTenancy({
                accountId,
                // A single claim means the account belongs to that customer alone. Conflicting
                // claims are not a dedication, the account is treated as shared.
                dedicatedTo: claims.length === 1 ? claims[0] : undefined,
                tenants: tenants[accountId].slice().sort(),
            });
            return acc;
        }, {} as Record<string, AccountTenancy>);
    }
}
